var SK_PALETTE = ['#5E6AD2','#22D3EE','#10B981','#F5A623','#A78BFA','#EF4444','#38BDF8','#F472B6'];

function parseFlows(text){
  var lines = String(text == null ? '' : text).split(/\r?\n/);
  var links = [], errors = [];
  for (var i = 0; i < lines.length; i++){
    var l = lines[i].trim();
    if (!l || l.charAt(0) === '#') continue;
    var m = /^(.+?)\s*(?:->|=>|→)\s*(.+?)\s*[:：\[]\s*(-?[\d.]+)\s*\]?$/.exec(l);
    if (!m){ errors.push({ line:i + 1, text:l, why:'格式应为 源 -> 目标: 数值' }); continue; }
    var v = parseFloat(m[3]);
    if (!isFinite(v) || v <= 0){ errors.push({ line:i + 1, text:l, why:'数值必须为正数' }); continue; }
    var from = m[1].trim(), to = m[2].trim();
    if (!from || !to){ errors.push({ line:i + 1, text:l, why:'节点名为空' }); continue; }
    if (from === to){ errors.push({ line:i + 1, text:l, why:'自环流不被支持' }); continue; }
    links.push({ from:from, to:to, value:v });
  }
  return { links:links, errors:errors };
}

function mergeLinks(links){
  var map = {}, order = [];
  for (var i = 0; i < links.length; i++){
    var k = links[i].from + '\u0001' + links[i].to;
    if (map[k] === undefined){ map[k] = links.length ? order.length : 0; order.push({ from:links[i].from, to:links[i].to, value:0 }); map[k] = order.length - 1; }
    order[map[k]].value += links[i].value;
  }
  return order;
}

function nodeList(links){
  var seen = {}, out = [];
  for (var i = 0; i < links.length; i++){
    if (!seen[links[i].from]){ seen[links[i].from] = 1; out.push(links[i].from); }
    if (!seen[links[i].to]){ seen[links[i].to] = 1; out.push(links[i].to); }
  }
  return out;
}

function assignLayers(links){
  var names = nodeList(links), inc = {}, adj = {};
  for (var i = 0; i < names.length; i++){ inc[names[i]] = []; adj[names[i]] = []; }
  for (var j = 0; j < links.length; j++){ adj[links[j].from].push(links[j].to); inc[links[j].to].push(links[j].from); }
  var layer = {}, guard = {}, capped = false;
  function depth(n, d){
    if (d > names.length){ capped = true; return 0; }
    if (layer[n] !== undefined) return layer[n];
    if (guard[n]){ capped = true; return 0; }
    guard[n] = 1;
    var best = 0;
    for (var k = 0; k < inc[n].length; k++) best = Math.max(best, depth(inc[n][k], d + 1) + 1);
    guard[n] = 0;
    layer[n] = best;
    return best;
  }
  for (var m = 0; m < names.length; m++) depth(names[m], 0);
  var maxLayer = 0;
  for (var q = 0; q < names.length; q++) maxLayer = Math.max(maxLayer, layer[names[q]]);
  for (var s = 0; s < names.length; s++){
    if (!adj[names[s]].length) layer[names[s]] = maxLayer;
  }
  return { layer:layer, names:names, maxLayer:maxLayer, cyclic:capped, adj:adj, inc:inc };
}

function nodeTotals(links){
  var t = {};
  function touch(n){ if (!t[n]) t[n] = { name:n, inSum:0, outSum:0 }; }
  for (var i = 0; i < links.length; i++){
    touch(links[i].from); touch(links[i].to);
    t[links[i].from].outSum += links[i].value;
    t[links[i].to].inSum += links[i].value;
  }
  for (var k in t) if (Object.prototype.hasOwnProperty.call(t, k)) t[k].value = Math.max(t[k].inSum, t[k].outSum);
  return t;
}

function balanceCheck(links){
  var t = nodeTotals(links), out = [];
  for (var k in t){
    if (!Object.prototype.hasOwnProperty.call(t, k)) continue;
    var n = t[k];
    if (n.inSum > 0 && n.outSum > 0 && Math.abs(n.inSum - n.outSum) > 1e-9){
      out.push({ name:n.name, inSum:round3(n.inSum), outSum:round3(n.outSum), delta:round3(n.outSum - n.inSum) });
    }
  }
  out.sort(function(a, b){ return Math.abs(b.delta) - Math.abs(a.delta); });
  return out;
}

function round3(n){ return Math.round(n * 1000) / 1000; }

function layout(links, opt){
  opt = opt || {};
  var W = opt.width || 680, H = opt.height || 360;
  var pad = opt.pad || 24, nodeW = opt.nodeW || 12, gap = opt.gap || 8;
  var merged = mergeLinks(links);
  if (!merged.length) return { nodes:[], ribbons:[], width:W, height:H, empty:true };
  var la = assignLayers(merged), totals = nodeTotals(merged);
  var cols = {}, i;
  for (i = 0; i < la.names.length; i++){
    var lv = la.layer[la.names[i]];
    (cols[lv] = cols[lv] || []).push(la.names[i]);
  }
  var maxLayer = la.maxLayer;
  var colX = function(l){ return maxLayer === 0 ? pad : pad + l * ((W - pad * 2 - nodeW) / maxLayer); };
  var maxColSum = 0;
  for (var c in cols){
    if (!Object.prototype.hasOwnProperty.call(cols, c)) continue;
    var s = 0;
    for (i = 0; i < cols[c].length; i++) s += totals[cols[c][i]].value;
    maxColSum = Math.max(maxColSum, s);
  }
  var maxCount = 0;
  for (var c2 in cols) if (Object.prototype.hasOwnProperty.call(cols, c2)) maxCount = Math.max(maxCount, cols[c2].length);
  var avail = H - pad * 2 - gap * Math.max(0, maxCount - 1);
  var scale = maxColSum > 0 ? avail / maxColSum : 1;
  var nodes = {}, order = [];
  for (var lv2 in cols){
    if (!Object.prototype.hasOwnProperty.call(cols, lv2)) continue;
    var list = cols[lv2].slice().sort(function(a, b){ return totals[b].value - totals[a].value || (a < b ? -1 : 1); });
    var y = pad;
    for (i = 0; i < list.length; i++){
      var nm = list[i], h = Math.max(2, totals[nm].value * scale);
      var nd = { name:nm, layer:parseInt(lv2, 10), x:colX(parseInt(lv2, 10)), y:y, w:nodeW, h:h,
                 value:round3(totals[nm].value), inSum:round3(totals[nm].inSum), outSum:round3(totals[nm].outSum),
                 color:SK_PALETTE[parseInt(lv2, 10) % SK_PALETTE.length], outCursor:y, inCursor:y };
      nodes[nm] = nd; order.push(nd);
      y += h + gap;
    }
  }
  var sorted = merged.slice().sort(function(a, b){ return nodes[a.from].y - nodes[b.from].y || nodes[a.to].y - nodes[b.to].y; });
  var ribbons = [];
  for (i = 0; i < sorted.length; i++){
    var lk = sorted[i], a = nodes[lk.from], b = nodes[lk.to];
    var th = Math.max(1, lk.value * scale);
    var y0 = a.outCursor, y1 = b.inCursor;
    a.outCursor += th; b.inCursor += th;
    ribbons.push({ from:lk.from, to:lk.to, value:round3(lk.value), thickness:round3(th),
                   x0:a.x + a.w, y0:y0, x1:b.x, y1:y1, color:a.color });
  }
  return { nodes:order, ribbons:ribbons, width:W, height:H, scale:scale, maxLayer:maxLayer, cyclic:la.cyclic, empty:false };
}

function ribbonPath(r){
  var x0 = r.x0, x1 = r.x1, t = r.thickness;
  var cx = (x0 + x1) / 2;
  var top0 = r.y0, top1 = r.y1;
  return 'M' + f(x0) + ',' + f(top0) +
         ' C' + f(cx) + ',' + f(top0) + ' ' + f(cx) + ',' + f(top1) + ' ' + f(x1) + ',' + f(top1) +
         ' L' + f(x1) + ',' + f(top1 + t) +
         ' C' + f(cx) + ',' + f(top1 + t) + ' ' + f(cx) + ',' + f(top0 + t) + ' ' + f(x0) + ',' + f(top0 + t) + ' Z';
}

function f(n){ return Math.round(n * 100) / 100; }

function escXml(s){
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function toSvg(lay, opt){
  opt = opt || {};
  if (!lay || lay.empty) return '<svg xmlns="http://www.w3.org/2000/svg" width="' + ((lay && lay.width) || 680) + '" height="' + ((lay && lay.height) || 360) + '"></svg>';
  var out = ['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ' + lay.width + ' ' + lay.height + '" width="100%" height="' + lay.height + '" role="img" aria-label="桑基流向图">'];
  out.push('<rect width="' + lay.width + '" height="' + lay.height + '" fill="#0A0A0B"/>');
  for (var i = 0; i < lay.ribbons.length; i++){
    var r = lay.ribbons[i];
    out.push('<path d="' + ribbonPath(r) + '" fill="' + r.color + '" fill-opacity="' + (opt.opacity || 0.32) + '"><title>' + escXml(r.from + ' → ' + r.to + ': ' + r.value) + '</title></path>');
  }
  for (var j = 0; j < lay.nodes.length; j++){
    var n = lay.nodes[j];
    out.push('<rect x="' + f(n.x) + '" y="' + f(n.y) + '" width="' + n.w + '" height="' + f(n.h) + '" rx="2" fill="' + n.color + '"><title>' + escXml(n.name + ': ' + n.value) + '</title></rect>');
    var anchor = n.layer === lay.maxLayer ? 'end' : 'start';
    var tx = n.layer === lay.maxLayer ? n.x - 6 : n.x + n.w + 6;
    out.push('<text x="' + f(tx) + '" y="' + f(n.y + n.h / 2 + 4) + '" fill="#A1A1AA" font-size="11" text-anchor="' + anchor + '" font-family="system-ui,sans-serif">' + escXml(n.name) + ' ' + n.value + '</text>');
  }
  out.push('</svg>');
  return out.join('');
}

function summary(links){
  var merged = mergeLinks(links);
  var totals = nodeTotals(merged), la = assignLayers(merged);
  var sources = [], sinks = [], total = 0;
  for (var k in totals){
    if (!Object.prototype.hasOwnProperty.call(totals, k)) continue;
    if (totals[k].inSum === 0){ sources.push(k); total += totals[k].outSum; }
    if (totals[k].outSum === 0) sinks.push(k);
  }
  var biggest = merged.slice().sort(function(a, b){ return b.value - a.value; })[0] || null;
  return { nodes:la.names.length, links:merged.length, layers:la.maxLayer + 1, sources:sources.sort(), sinks:sinks.sort(),
           throughput:round3(total), biggest:biggest, cyclic:la.cyclic, unbalanced:balanceCheck(merged) };
}

var SankeyForgePure = {
  parseFlows: parseFlows, mergeLinks: mergeLinks, nodeList: nodeList, assignLayers: assignLayers,
  nodeTotals: nodeTotals, balanceCheck: balanceCheck, layout: layout, ribbonPath: ribbonPath,
  toSvg: toSvg, summary: summary, PALETTE: SK_PALETTE
};
if (typeof module !== 'undefined' && module.exports) module.exports = SankeyForgePure;
if (typeof window !== 'undefined') window.SankeyForgePure = SankeyForgePure;
